using Npgsql;namespace Backend.Helpers;public static class PostgresErrorHelper{    private const string SerializationFailureSqlState = "40001";    public static bool IsSerializationFailure(Exception ex)    {        var current = ex;        while (current is not null)        {            if (current is PostgresException pgEx                && pgEx.SqlState == SerializationFailureSqlState)            {                return true;            }            current = current.InnerException;        }        return false;    }}